using System.Windows.Controls;using LibraryManager.Services;namespace LibraryManager.Views;public partial class SettingsView:UserControl{public SettingsView(){InitializeComponent();var p=VH.Page(Root,"تنظیمات کتابخانه");var fee=VH.Input(p,"حق عضویت (تومان)",SettingsService.Get("MembershipFeeAmount","20000"));var fine=VH.Input(p,"جریمه روزانه (تومان)",SettingsService.Get("FineAmountPerDay","500"));var days=VH.Input(p,"مدت امانت (روز)",SettingsService.Get("LoanPeriodDays","7"));var max=VH.Input(p,"حداکثر امانت فعال",SettingsService.Get("MaxActiveLoansPerMember","2"));p.Children.Add(VH.Btn("ذخیره",(s,e)=>{try{_=decimal.Parse(fee.Text);_=decimal.Parse(fine.Text);_=int.Parse(days.Text);_=int.Parse(max.Text);SettingsService.Save("MembershipFeeAmount",fee.Text);SettingsService.Save("FineAmountPerDay",fine.Text);SettingsService.Save("LoanPeriodDays",days.Text);SettingsService.Save("MaxActiveLoansPerMember",max.Text);System.Windows.MessageBox.Show("تنظیمات ذخیره شد.");}catch(Exception ex){VH.Error(ex);}}));}}